        cover.id = 'slide-cover';
        document.body.appendChild(cover);
        function slideBg(mode) {
            if (mode === 'black') return '#000000';
            if (mode === 'blank') return config.theme === 'light' ? '#fafafa' : '#444444';
            return null;
        }

